spec_raw:
{
  "cleaner": {
    "params": {
      "drop_if_constant": {
        "choice": [false, true]
      }
    }
  },
  "vectorizer": {
    "slots": {
      "numeric": [
        "sklearn.preprocessing.StandardScaler",
        "sklearn.preprocessing.RobustScaler"
      ]
    }
  },
  "scoped_encodings": [
    {
      "name": "geo_cluster",
      "cols": ["longitude", "latitude"],
      "options": [
        "skip",
        {
          "name": "sklearn.cluster.MiniBatchKMeans",
          "params": {
            "n_clusters": {
              "int": [5, 20]
            }
          }
        },
        {
          "name": "sklearn.preprocessing.KBinsDiscretizer",
          "params": {
            "n_bins": {
              "int": [5, 15]
            },
            "encode": {
              "choice": ["ordinal", "onehot"]
            }
          }
        }
      ],
      "position": "pre_encode",
      "additive": true
    }
  ],
  "stages": [
    {
      "name": "scale",
      "options": [
        "skip",
        "sklearn.preprocessing.StandardScaler",
        "sklearn.preprocessing.RobustScaler"
      ]
    },
    {
      "name": "feature_eng",
      "options": [
        "skip",
        {
          "name": "sklearn.preprocessing.PolynomialFeatures",
          "params": {
            "degree": {
              "int": [2, 3]
            },
            "interaction_only": {
              "choice": [false, true]
            }
          }
        }
      ]
    }
  ],
  "model": [
    {
      "name": "sklearn.ensemble.HistGradientBoostingRegressor",
      "prior": 0.8,
      "params": {
        "learning_rate": {
          "float": [0.01, 0.3],
          "log": true
        },
        "max_iter": {
          "int": [100, 600]
        },
        "max_depth": {
          "int": [2, 16]
        },
        "l2_regularization": {
          "float": [0.0, 1.0]
        }
      }
    },
    {
      "name": "xgboost.XGBRegressor",
      "prior": 0.7,
      "params": {
        "n_estimators": {
          "int": [100, 500]
        },
        "learning_rate": {
          "float": [0.01, 0.3],
          "log": true
        },
        "max_depth": {
          "int": [2, 12]
        },
        "subsample": {
          "float": [0.5, 1.0]
        },
        "colsample_bytree": {
          "float": [0.5, 1.0]
        },
        "reg_lambda": {
          "float": [0.0, 5.0]
        }
      }
    },
    {
      "name": "lightgbm.LGBMRegressor",
      "prior": 0.7,
      "params": {
        "n_estimators": {
          "int": [100, 500]
        },
        "learning_rate": {
          "float": [0.01, 0.3],
          "log": true
        },
        "num_leaves": {
          "int": [15, 100]
        },
        "max_depth": {
          "int": [3, 16]
        },
        "colsample_bytree": {
          "float": [0.5, 1.0]
        },
        "reg_lambda": {
          "float": [0.0, 5.0]
        }
      }
    },
    {
      "name": "sklearn.linear_model.Ridge",
      "prior": 0.3,
      "params": {
        "alpha": {
          "float": [0.001, 1000.0],
          "log": true
        }
      }
    }
  ]
}
